private void btnUpdateFinal_Click(object sender, EventArgs e)
{
    try
    {
        if (dtbData == null || dtbData.Rows.Count == 0)
        {
            MessageManager.Warning("Không có dữ liệu để cập nhật!");
            return;
        }

        if (MessageManager.Question("Bạn có chắc muốn cập nhật Số giờ chuẩn (TotalFinal) cho dữ liệu hiện tại?") != DialogResult.Yes)
            return;

        object semester = null;
        if (!chkIsFullYear.Checked && uYearSemester.SemesterEditValue != null)
            semester = uYearSemester.SemesterEditValueInt32;

        SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
        bool bolResult = obj.ExecuteNonQuery("SIM_TeachingTimeAdded_UpdateTotalFinal",
                        "@YearID", uYearSemester.YearIDEditValue,
                        "@Semester", semester,
                        "@TeacherWorkID", GetTeacherWorkIDFilter()
                        );

        if (bolResult)
        {
            MessageManager.Information("Cập nhật Số giờ chuẩn thành công!");

            new Thread(LoadData).Start();
        }
        else
        {
            ErrorManager.Error("Cập nhật thất bại!");
        }
    }
    catch (Exception ex)
    {
        ErrorManager.Error(ex.Message);
    }
}

