private void btnUpdateFinal_Click(object sender, EventArgs e)
{
    try
    {
        if (dtbData == null || dtbData.Rows.Count == 0)
        {
            MessageManager.Warning("Không có dữ liệu để cập nhật!");
            return;
        }

        if (MessageManager.Question("Bạn có chắc muốn cập nhật Số giờ chuẩn (TotalFinal) cho dữ liệu hiện tại?") != DialogResult.Yes)
            return;

        object semester = null;
        if (!chkIsFullYear.Checked && uYearSemester.SemesterEditValue != null)
            semester = uYearSemester.SemesterEditValueInt32;

        using (SqlConnection cnn = new SqlConnection(SystemService.SIMSConnectionString))
        {
            cnn.Open();

            using (SqlCommand cmd = new SqlCommand("SIM_TeachingTimeAdded_UpdateTotalFinal", cnn))
            {
                cmd.CommandType = CommandType.StoredProcedure;

                cmd.Parameters.AddWithValue("@YearID", uYearSemester.YearIDEditValue);

                if (semester != null)
                    cmd.Parameters.AddWithValue("@Semester", semester);
                else
                    cmd.Parameters.AddWithValue("@Semester", DBNull.Value);

                object objTeacherWorkID = GetTeacherWorkIDFilter();
                if (objTeacherWorkID != null)
                    cmd.Parameters.AddWithValue("@TeacherWorkID", objTeacherWorkID);
                else
                    cmd.Parameters.AddWithValue("@TeacherWorkID", DBNull.Value);

                cmd.ExecuteNonQuery();
            }
        }

        MessageManager.Information("Cập nhật Số giờ chuẩn thành công!");

        new Thread(LoadData).Start();
    }
    catch (Exception ex)
    {
        ErrorManager.Error(ex.Message);
    }
}

